import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

const promptPath = new URL('./preflight-pr.md', import.meta.url);

function ordered(text, first, second) {
  assert.ok(text.includes(first), `missing ${first}`);
  assert.ok(text.includes(second), `missing ${second}`);
  assert.ok(text.indexOf(first) < text.indexOf(second), `${first} must precede ${second}`);
}

test('preflight materializes the complete review artifact before read-only fanout', async () => {
  const prompt = await readFile(promptPath, 'utf8');
  ordered(prompt, 'mktemp', 'Launch exactly four fresh-context `reviewer` agents in parallel');
  assert.match(prompt, /git diff --binary --find-renames "\$base"\.\.\.HEAD/);
  assert.match(prompt, /git diff --binary --find-renames HEAD/);
  assert.match(prompt, /git ls-files --others --exclude-standard -z/);
  assert.match(prompt, /git diff --binary --no-index -- \/dev\/null/);
  assert.match(prompt, /absolute path/);
});

test('every reviewer reads the complete artifact and never substitutes watchdog_diff', async () => {
  const prompt = await readFile(promptPath, 'utf8');
  assert.match(prompt, /Give each reviewer.*review artifact.*absolute path/s);
  assert.match(prompt, /read.*artifact from start to finish.*chunks/s);
  assert.match(prompt, /must not rely on `watchdog_diff`/);
  ordered(prompt, 'Synthesize the four reports', 'Remove the temporary review artifact');
});

